async function traverse(store, startId, options) {
  const pageSize = options.pageSize ?? 100;
  const maxDepth = options.maxDepth ?? Number.POSITIVE_INFINITY;
  const maxNodes = options.maxNodes ?? 1e4;
  const visited = /* @__PURE__ */ new Set([startId]);
  const nodes = [];
  const edges = [];
  const cyclesDetected = [];
  let truncated = false;
  let frontier = [startId];
  let depth = 0;
  while (frontier.length > 0 && depth < maxDepth) {
    const next = [];
    for (const nodeId of frontier) {
      let after;
      for (; ; ) {
        const page = options.direction === "ancestors" ? await store.adjacencyBySource({
          nodeId,
          type: options.relationshipType,
          after,
          limit: pageSize
        }) : await store.adjacencyByTarget({
          nodeId,
          type: options.relationshipType,
          after,
          limit: pageSize
        });
        for (const raw of page.items) {
          const rel = raw;
          edges.push(rel);
          const neighbour = options.direction === "ancestors" ? rel.target : rel.source;
          if (visited.has(neighbour)) {
            cyclesDetected.push(`${rel.source}->${rel.target}`);
            continue;
          }
          visited.add(neighbour);
          if (visited.size > maxNodes) {
            truncated = true;
            break;
          }
          next.push(neighbour);
        }
        if (truncated || page.nextAfter === null) break;
        after = page.nextAfter;
      }
      if (truncated) break;
    }
    depth += 1;
    for (const id of next) nodes.push({ id, depth });
    if (truncated) break;
    frontier = next;
  }
  nodes.sort((a, b) => a.depth - b.depth || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return { nodes, edges, cyclesDetected, truncated };
}

